const e="wutility",t="wUtility",a="wUtility/wUtility",s={aspnetEndpoints:["web/api"],sql:[{dir:"web/db",database:"demo"}],angularRoutes:"web/frontend/src/app/app.routes.ts"},n=[{id:"start",title:{en:"Getting started",fa:"شروع"}},{id:"desktop",title:{en:"The original desktop app",fa:"اپ دسکتاپ اصلی"}},{id:"sync",title:{en:"Schema compare and sync",fa:"مقایسه و همگام‌سازی schema"}},{id:"security",title:{en:"Keys, demo mode and the vault",fa:"کلیدها، حالت دمو و vault"}},{id:"forms",title:{en:"The configuration forms",fa:"فرم‌های تنظیمات"}},{id:"web",title:{en:"Angular and Azure",fa:"Angular و Azure"}}],i=[{id:"overview",group:"start",title:{en:"What wUtility is",fa:"wUtility چیست"},files:["README.md","web/README.md","wUtility.sln"],en:[{id:"what",h:"A schema sync tool from hospital deployments",p:["wUtility was built on a team that deployed a Hospital Information System (HIS) in Iran. Hospitals running the same product ended up with databases that had drifted apart: custom columns, missing indexes, out-of-date views and stored procedures. Writing a migration script by hand for every site did not scale, so wUtility compares two structurally similar SQL Server databases, a reference and a site, from SQL Server's own metadata, and brings the site in line. It also grew a handful of forms for site configuration that came up at every rollout: doctors and their price groups, the registry of each site's databases.","The original is a Windows desktop app in C# on .NET Framework 4.8 with WPF, DevExpress and Telerik controls, plus an empty Windows Service. Those licensed libraries are not in the repository, so it cannot be built from it alone."],examples:["what"]},{id:"port",h:"wUtility Web: the same job, rewritten",p:["`web/` is an independent web port: an ASP.NET Core Minimal API on .NET 10 with `Microsoft.Data.SqlClient`, and an Angular 18 app with standalone components. Translating the WPF XAML was not an option, since grids from licensed libraries cannot run in a browser. Instead each form's data behaviour (its queries, joins and writes) was read from the original `.xaml.cs` and written again against the same tables. The desktop code is left untouched beside it.","Not everything was ported. The desktop app kept connection strings for 13 modules in local app settings, encrypted with a key written in the source; the web port replaces that with a server-side vault rather than copy the pattern. The Projects tab maps the web port, since that is what Control Panel's `wutility-adapter` calls."],examples:["ported"]}],fa:[{id:"what",h:"یک ابزار همگام‌سازی schema از استقرار بیمارستان‌ها",p:["wUtility در تیمی ساخته شد که یک سیستم اطلاعات بیمارستانی (HIS) را در ایران مستقر می‌کرد. بیمارستان‌هایی که همان محصول را داشتند در نهایت دیتابیس‌هایی داشتند که از هم فاصله گرفته بودند: ستون‌های سفارشی، indexهای گم‌شده، viewها و stored procedureهای قدیمی. نوشتن دستی اسکریپت migration برای هر سایت مقیاس‌پذیر نبود، پس wUtility دو دیتابیس SQL Server با ساختار مشابه، یک مرجع و یک سایت، را از روی metadata‌ی خود SQL Server مقایسه می‌کند و سایت را هم‌راستای مرجع می‌کند. چند فرم هم برای تنظیمات سایت به آن اضافه شد که در هر استقرار لازم می‌شد: پزشکان و گروه‌های قیمتشان، و فهرست دیتابیس‌های هر سایت.","نسخه‌ی اصلی یک اپ دسکتاپ ویندوز با C# روی .NET Framework 4.8 است، با WPF و کنترل‌های DevExpress و Telerik، به‌علاوه‌ی یک Windows Service‌ی خالی. آن کتابخانه‌های دارای مجوز در مخزن نیستند، پس فقط از روی مخزن نمی‌شود آن را build کرد."],examples:["what"]},{id:"port",h:"wUtility Web: همان کار، از نو نوشته‌شده",p:["`web/` یک پورت وب مستقل است: یک Minimal API با ASP.NET Core روی .NET 10 که با `Microsoft.Data.SqlClient` کار می‌کند، و یک اپ Angular 18 با کامپوننت‌های standalone. ترجمه‌ی XAML‌ی WPF شدنی نبود، چون gridهای کتابخانه‌های دارای مجوز در مرورگر اجرا نمی‌شوند. به‌جایش رفتار داده‌ای هر فرم (queryها، joinها و نوشتن‌هایش) از `.xaml.cs` اصلی خوانده شد و دوباره روی همان جدول‌ها نوشته شد. کد دسکتاپ دست‌نخورده کنارش مانده است.","همه چیز پورت نشده است. اپ دسکتاپ connection stringهای 13 ماژول را در app settings محلی نگه می‌داشت، رمزگذاری‌شده با کلیدی که در خود کد نوشته شده بود؛ پورت وب به‌جای کپی کردن این الگو یک vault سمت سرور جایش گذاشته است. تب Projects پورت وب را نشان می‌دهد، چون همان چیزی است که `wutility-adapter`ی Control Panel صدا می‌زند."],examples:["ported"]}],examples:{what:{title:{en:"What it does",fa:"چه کار می‌کند"},lang:"markdown",file:"README.md",from:"## What it does",lines:6},ported:{title:{en:"What is ported so far",fa:"چه چیزی تا حالا پورت شده"},lang:"markdown",file:"web/README.md",from:"| Original WPF form | Web equivalent | Notes |",lines:7}},quiz:[{q:{en:"Why was the WPF app rewritten for the web instead of translated screen by screen?",fa:"چرا اپ WPF برای وب از نو نوشته شد به‌جای این‌که صفحه به صفحه ترجمه شود؟"},options:{en:["Its DevExpress and Telerik controls cannot run in a browser, so each form's queries and writes were reimplemented instead","Because the desktop code was lost","Because WPF cannot talk to SQL Server"],fa:["کنترل‌های DevExpress و Telerik آن در مرورگر اجرا نمی‌شوند، پس به‌جایش queryها و نوشتن‌های هر فرم از نو پیاده شد","چون کد دسکتاپ گم شده بود","چون WPF نمی‌تواند با SQL Server حرف بزند"]},answer:0,why:{en:"The web README says the forms' data behaviour was read from the .xaml.cs files and written again against the same tables.",fa:"README‌ی وب می‌گوید رفتار داده‌ای فرم‌ها از فایل‌های .xaml.cs خوانده شد و روی همان جدول‌ها دوباره نوشته شد."}},{q:{en:"Which desktop feature was deliberately not copied into the web port?",fa:"کدام قابلیت دسکتاپ عمداً در پورت وب کپی نشد؟"},options:{en:["The doctors list","Local app-settings connection strings encrypted with a key in the source","The schema comparison"],fa:["فهرست پزشکان","connection stringهای app settings محلی که با کلیدی در کد رمز شده‌اند","مقایسه‌ی schema"]},answer:1,why:{en:"That pattern has no safe equivalent in a shared web app; a server-side vault was built instead.",fa:"این الگو در یک اپ وب مشترک معادل امنی ندارد؛ به‌جایش یک vault سمت سرور ساخته شد."}}]},{id:"run",group:"start",title:{en:"Run it: an API key, the API, the Angular app",fa:"اجرا: یک API key، API، اپ Angular"},files:["web/README.md","web/api/Program.cs","web/api/Properties/launchSettings.json","web/api/appsettings.json","web/frontend/proxy.conf.js","web/tools/DbSetup/Program.cs"],en:[{id:"key",h:"No key, no start",p:["The API runs on port 5091 and the Angular dev server on 4300, and both need the same `WUTILITY_API_KEY` in the environment. The API refuses to start unless the key is at least 32 characters, and there is no default. That is on purpose: `/api/execute` runs a script against whatever server it is given, and without the key it would be an open SQL runner for anyone who could reach the port.","The four demo databases come from `web/db/*.sql`. `tools/DbSetup` runs them in order against a local SQL Server with Windows authentication, creating each database when it is missing; `--prefix` gives them other names, so a test run never touches the existing demo databases."],examples:["commands","key"]},{id:"proxy",h:"The key stays on the server side",p:["The Angular app calls a relative `/api` and never sees the key. In development `ng serve` proxies `/api` to the API through `proxy.conf.js`, which adds `X-Api-Key` itself on the server side, so the key is never compiled into the browser bundle; the proxy, too, refuses to start without it. Control Panel's `wutility-adapter` sends the same header.",'The table lists every endpoint. "Anyone" there means no ASP.NET authorization policy: the key check is a middleware in front of every `/api` route instead, described in the security topics.'],examples:["proxy","plan"],data:{kind:"endpoints"}}],fa:[{id:"key",h:"بدون کلید، بدون شروع",p:["API روی پورت 5091 و سرور توسعه‌ی Angular روی 4300 اجرا می‌شوند، و هر دو همان `WUTILITY_API_KEY` را در محیط لازم دارند. API بالا نمی‌آید مگر این‌که کلید دست‌کم 32 نویسه باشد، و هیچ مقدار پیش‌فرضی وجود ندارد. این عمدی است: `/api/execute` یک اسکریپت را روی هر سروری که به آن داده شود اجرا می‌کند، و بدون کلید برای هر کسی که به پورت دسترسی دارد یک اجراکننده‌ی SQL‌ی باز می‌شد.","چهار دیتابیس نمایشی از `web/db/*.sql` می‌آیند. `tools/DbSetup` آن‌ها را به ترتیب روی یک SQL Server محلی با Windows authentication اجرا می‌کند و هر دیتابیس را اگر نباشد می‌سازد؛ `--prefix` اسم‌های دیگری به آن‌ها می‌دهد، تا یک اجرای آزمایشی هرگز به دیتابیس‌های نمایشی موجود دست نزند."],examples:["commands","key"]},{id:"proxy",h:"کلید سمت سرور می‌ماند",p:["اپ Angular یک `/api` نسبی را صدا می‌زند و هرگز کلید را نمی‌بیند. در توسعه `ng serve` مسیر `/api` را از طریق `proxy.conf.js` به API می‌فرستد که خودش سمت سرور `X-Api-Key` را اضافه می‌کند، پس کلید هرگز در bundle‌ی مرورگر کامپایل نمی‌شود؛ proxy هم بدون آن بالا نمی‌آید. `wutility-adapter`ی Control Panel همین هدر را می‌فرستد.",'جدول همه‌ی endpointها را نشان می‌دهد. "همه" در آن یعنی هیچ policy‌ی authorization‌ی ASP.NET وجود ندارد: به‌جایش بررسی کلید یک middleware جلوی همه‌ی مسیرهای `/api` است، که در موضوع‌های امنیت توضیح داده شده.'],examples:["proxy","plan"],data:{kind:"endpoints"}}],examples:{commands:{title:{en:"Run it",fa:"اجرا"},lang:"bash",file:"web/README.md",from:"# PowerShell: $env:WUTILITY_API_KEY",lines:3},key:{title:{en:"At least 32 characters, no default",fa:"دست‌کم 32 نویسه، بدون پیش‌فرض"},lang:"csharp",file:"web/api/Program.cs",from:'var apiKey = builder.Configuration["WUTILITY_API_KEY"];',lines:7},proxy:{title:{en:"The proxy adds the key",fa:"proxy کلید را اضافه می‌کند"},lang:"javascript",file:"web/frontend/proxy.conf.js",from:"const apiKey = process.env.WUTILITY_API_KEY;",lines:13},plan:{title:{en:"Script to database",fa:"اسکریپت به دیتابیس"},lang:"csharp",file:"web/tools/DbSetup/Program.cs",from:"var plan = new (string Script, string Database)[]",lines:7}},quiz:[{q:{en:"Why is the API key added by proxy.conf.js and not by the Angular code?",fa:"چرا API key را proxy.conf.js اضافه می‌کند و نه کد Angular؟"},options:{en:["Angular cannot set headers","Anything in the Angular code ships to the browser, where anyone could read the key","The proxy is faster"],fa:["Angular نمی‌تواند هدر بگذارد","هر چیزی در کد Angular به مرورگر می‌رسد، جایی که هر کسی می‌تواند کلید را بخواند","proxy سریع‌تر است"]},answer:1,why:{en:"The proxy runs in Node on the developer's machine and adds the header server-side; the bundle only knows /api.",fa:"proxy در Node روی ماشین توسعه‌دهنده اجرا می‌شود و هدر را سمت سرور اضافه می‌کند؛ bundle فقط /api را می‌شناسد."}},{q:{en:"WUTILITY_API_KEY is set to a 16-character value. What happens when the API starts?",fa:"WUTILITY_API_KEY یک مقدار 16 نویسه‌ای دارد. وقتی API شروع می‌شود چه می‌شود؟"},options:{en:["It starts and pads the key","It starts in demo mode","It throws InvalidOperationException and does not start"],fa:["شروع می‌شود و کلید را تکمیل می‌کند","در حالت دمو شروع می‌شود","InvalidOperationException می‌دهد و شروع نمی‌شود"]},answer:2,why:{en:"Program.cs checks for an empty key or one shorter than 32 characters before anything else is configured.",fa:"Program.cs قبل از هر تنظیم دیگری کلید خالی یا کوتاه‌تر از 32 نویسه را بررسی می‌کند."}}]},{id:"tests",group:"start",title:{en:"How it is tested",fa:"چطور تست می‌شود"},files:["web/README.md","web/deploy/azure/deploy.ps1","web/db/02-schemasync-target.sql"],en:[{id:"manual",h:"Against real databases, not mocks",p:["There is no automated test project in the repository. The web port was tested by hand against real SQL Server on `(local)`, using dedicated demo databases and never the hospital databases on the same instance. The README records what was checked: the comparison found a missing table, a missing column and a type mismatch; the generated script was executed; a second comparison found nothing left. The doctors to price-groups pages were used through the browser, and the inserts and updates were looked at in the database.","The demo data is built to make that test repeatable. `02-schemasync-target.sql` creates a target with exactly one of each difference `SchemaDiffer` reports: a missing table, a missing column, a type mismatch and a nullability mismatch. Comparing it with the source must show four rows; applying the script and comparing again must show none."],examples:["tested"]},{id:"smoke",h:"A smoke test after every deployment",p:["The Azure deployment script ends by testing the live site: `/healthz` must answer, `/api/demo` must say demo mode is on (a deployment without it would expose the real powers of the API), and one comparison must run through to the database, with a 180-second timeout because a paused serverless database may need a minute to resume. If any of these fails the script stops with an error."],examples:["smoke"]}],fa:[{id:"manual",h:"روی دیتابیس واقعی، نه mock",p:["در مخزن هیچ پروژه‌ی تست خودکاری نیست. پورت وب دستی روی یک SQL Server واقعی روی `(local)` تست شده، با دیتابیس‌های نمایشی جداگانه و هرگز با دیتابیس‌های بیمارستان روی همان instance. README چیزهایی را که بررسی شده ثبت کرده: مقایسه یک جدول گم‌شده، یک ستون گم‌شده و یک ناهماهنگی نوع را پیدا کرد؛ اسکریپت تولیدشده اجرا شد؛ مقایسه‌ی دوم چیزی پیدا نکرد. صفحه‌های پزشکان و گروه‌های قیمت از طریق مرورگر استفاده شدند و insertها و updateها در دیتابیس دیده شدند.","داده‌ی نمایشی طوری ساخته شده که این تست تکرارپذیر باشد. `02-schemasync-target.sql` مقصدی می‌سازد که دقیقاً از هر تفاوتی که `SchemaDiffer` گزارش می‌دهد یکی دارد: یک جدول گم‌شده، یک ستون گم‌شده، یک ناهماهنگی نوع و یک ناهماهنگی nullability. مقایسه‌ی آن با مبدأ باید چهار ردیف نشان دهد؛ اجرای اسکریپت و مقایسه‌ی دوباره باید هیچ ردیفی نشان ندهد."],examples:["tested"]},{id:"smoke",h:"یک smoke test بعد از هر استقرار",p:["اسکریپت استقرار Azure با تست سایت زنده تمام می‌شود: `/healthz` باید جواب بدهد، `/api/demo` باید بگوید حالت دمو روشن است (استقراری بدون آن، قدرت‌های واقعی API را در معرض می‌گذاشت)، و یک مقایسه باید تا خود دیتابیس اجرا شود، با timeout‌ی 180 ثانیه‌ای چون یک دیتابیس serverless‌ی متوقف‌شده ممکن است یک دقیقه برای بیدار شدن لازم داشته باشد. اگر هر کدام شکست بخورد، اسکریپت با خطا متوقف می‌شود."],examples:["smoke"]}],examples:{tested:{title:{en:"What was tested",fa:"چه چیزی تست شد"},lang:"markdown",file:"web/README.md",from:"## Testing performed",lines:6},smoke:{title:{en:"The smoke test",fa:"smoke test"},lang:"powershell",file:"web/deploy/azure/deploy.ps1",from:"Step 'Smoke test'",to:'Write-Host "healthz ok'}},quiz:[{q:{en:"Why does the demo target database have exactly one difference of each kind?",fa:"چرا دیتابیس مقصد نمایشی از هر نوع تفاوت دقیقاً یکی دارد؟"},options:{en:["So one compare-apply-compare run exercises every path of the differ and the generator, and the result is easy to check","Because SQL Server allows only four changes","To keep the database small for Azure"],fa:["تا یک دور مقایسه-اجرا-مقایسه همه‌ی مسیرهای differ و generator را امتحان کند و نتیجه ساده قابل بررسی باشد","چون SQL Server فقط چهار تغییر اجازه می‌دهد","تا دیتابیس برای Azure کوچک بماند"]},answer:0,why:{en:"Four diff kinds, four diffs: after the script runs, a second compare must report zero.",fa:"چهار نوع تفاوت، چهار تفاوت: بعد از اجرای اسکریپت، مقایسه‌ی دوم باید صفر گزارش کند."}},{q:{en:"Why does the smoke test fail if /api/demo says demo mode is off?",fa:"چرا smoke test وقتی /api/demo بگوید حالت دمو خاموش است شکست می‌خورد؟"},options:{en:["The health check depends on it","A public deployment without demo mode would let visitors run any script on any server, if they had the key","Demo mode makes the site faster"],fa:["health check به آن وابسته است","یک استقرار عمومی بدون حالت دمو به بازدیدکنندگان اجازه می‌داد هر اسکریپتی را روی هر سروری اجرا کنند، اگر کلید را داشتند","حالت دمو سایت را سریع‌تر می‌کند"]},answer:1,why:{en:"Demo mode is what constrains compare, execute and the vault on the public site; the script refuses to call a deployment done without it.",fa:"حالت دمو همان چیزی است که مقایسه، اجرا و vault را در سایت عمومی محدود می‌کند؛ اسکریپت استقراری بدون آن را تمام‌شده حساب نمی‌کند."}}]},{id:"wpf",group:"desktop",title:{en:"The desktop compare form",fa:"فرم مقایسه‌ی دسکتاپ"},files:["wUtility/SimilarityDatabaseForm.xaml.cs","wUtility/Utils/DBHelper.cs","wUtility/MainWindow.xaml.cs"],en:[{id:"meta",h:"Everything from metadata",p:["`SimilarityDatabaseForm` is the heart of the desktop app, about 1,800 lines of code-behind. For both databases it reads SQL Server's catalog into `DataTable`s: columns and constraints from `INFORMATION_SCHEMA.COLUMNS` and `TABLE_CONSTRAINTS`, views from `INFORMATION_SCHEMA.VIEWS`, stored procedures with their text through `object_definition`, functions from `sys.sql_modules`, indexes from `sys.indexes` and `sys.index_columns`. Comparing then means joining the two tables with LINQ on the name and keeping what has no partner on the other side.","Because the definitions themselves are read, a missing view or procedure can be created on the site from the reference's own text, which a list of names alone could not do. The form also works in both directions (`IsDatasourceMode`), so the same code finds what the site lacks and what it has extra."],examples:["sps","views"]},{id:"direct",h:"Applied straight away",p:["The desktop form changes the site directly. `ChngeDataType` builds an `ALTER TABLE ... ALTER COLUMN` per row by string concatenation, drops the column's default constraint if it has one, runs the change, and recreates the default with a fixed value (`''` for text, `1` otherwise), all through `DBHelper.ExecuteQuery` with a 30-minute command timeout. A `varchar` of length 10 is even widened to 50 on the way. Nothing is shown for review first, and a failure halfway leaves the site partly changed.","Those are the points the web port changes: it generates a script to read before anything runs, and runs it batch by batch, reporting where it stopped."],examples:["widen","alter"]}],fa:[{id:"meta",h:"همه چیز از metadata",p:["`SimilarityDatabaseForm` قلب اپ دسکتاپ است، حدود 1800 خط code-behind. برای هر دو دیتابیس catalog‌ی SQL Server را در `DataTable`ها می‌خواند: ستون‌ها و قیدها از `INFORMATION_SCHEMA.COLUMNS` و `TABLE_CONSTRAINTS`، viewها از `INFORMATION_SCHEMA.VIEWS`، stored procedureها با متنشان از راه `object_definition`، تابع‌ها از `sys.sql_modules`، indexها از `sys.indexes` و `sys.index_columns`. بعد مقایسه یعنی join کردن دو جدول با LINQ روی اسم و نگه داشتن چیزی که در طرف دیگر جفت ندارد.","چون خود تعریف‌ها خوانده می‌شوند، یک view یا procedure‌ی گم‌شده را می‌شود در سایت از متن خود مرجع ساخت، کاری که فقط با فهرست اسم‌ها شدنی نبود. فرم در هر دو جهت هم کار می‌کند (`IsDatasourceMode`)، پس همان کد هم چیزی را پیدا می‌کند که سایت ندارد و هم چیزی را که اضافه دارد."],examples:["sps","views"]},{id:"direct",h:"بلافاصله اعمال‌شده",p:["فرم دسکتاپ سایت را مستقیم تغییر می‌دهد. `ChngeDataType` برای هر ردیف با چسباندن رشته‌ها یک `ALTER TABLE ... ALTER COLUMN` می‌سازد، اگر ستون default constraint داشته باشد آن را حذف می‌کند، تغییر را اجرا می‌کند، و default را با یک مقدار ثابت (`''` برای متن، `1` برای بقیه) دوباره می‌سازد، همه از طریق `DBHelper.ExecuteQuery` با timeout‌ی 30 دقیقه‌ای. حتی یک `varchar` به طول 10 در این مسیر به 50 بزرگ می‌شود. هیچ چیزی قبلش برای بررسی نشان داده نمی‌شود، و شکست در وسط کار سایت را نیمه‌تغییریافته رها می‌کند.","همین‌ها نقطه‌هایی هستند که پورت وب عوض می‌کند: اسکریپتی تولید می‌کند که قبل از اجرای هر چیزی خوانده شود، و آن را دسته به دسته اجرا می‌کند و می‌گوید کجا متوقف شد."],examples:["widen","alter"]}],examples:{sps:{title:{en:"Procedures with their text",fa:"procedureها با متنشان"},lang:"csharp",file:"wUtility/SimilarityDatabaseForm.xaml.cs",from:'string query = @"SELECT ROW_NUMBER() OVER(ORDER BY ROUTINE_CATALOG)',lines:3},views:{title:{en:"What has no partner on the other side",fa:"چیزی که در طرف دیگر جفت ندارد"},lang:"csharp",file:"wUtility/SimilarityDatabaseForm.xaml.cs",from:"discordResult = dataTable1.AsEnumerable().Where(o => !(result.Where",lines:3},widen:{title:{en:"10 becomes 50",fa:"10 می‌شود 50"},lang:"csharp",file:"wUtility/SimilarityDatabaseForm.xaml.cs",from:"if (characterMaximumLength == (10).ToString())",lines:2},alter:{title:{en:"Drop the default, alter, recreate",fa:"حذف default، تغییر، ساخت دوباره"},lang:"csharp",file:"wUtility/SimilarityDatabaseForm.xaml.cs",from:"if (dataTable.Rows.Count > 0)",to:"dbh.ExecuteQuery(createConstraint);"}},quiz:[{q:{en:"Why does the desktop form read procedure text with object_definition rather than only their names?",fa:"چرا فرم دسکتاپ متن procedureها را با object_definition می‌خواند و نه فقط اسمشان را؟"},options:{en:["Names are not unique in SQL Server","object_definition is faster","With the text, a procedure missing on the site can be created from the reference's own definition"],fa:["اسم‌ها در SQL Server یکتا نیستند","object_definition سریع‌تر است","با متن، procedure‌ی گم‌شده در سایت را می‌شود از تعریف خود مرجع ساخت"]},answer:2,why:{en:"A list of names can only say what is missing; the definition is what lets CreateDiscordSps recreate it.",fa:"فهرست اسم‌ها فقط می‌تواند بگوید چه چیزی گم شده؛ تعریف است که اجازه می‌دهد CreateDiscordSps آن را بسازد."}},{q:{en:"What is the main risk of how ChngeDataType applies changes?",fa:"بزرگ‌ترین خطر روشی که ChngeDataType تغییرها را اعمال می‌کند چیست؟"},options:{en:["It runs each change immediately with no review, so a failure part way leaves the site half changed","It is too slow","It cannot change decimal columns"],fa:["هر تغییر را بدون بررسی فوراً اجرا می‌کند، پس شکست در وسط کار سایت را نیمه‌تغییریافته رها می‌کند","خیلی کند است","نمی‌تواند ستون‌های decimal را تغییر دهد"]},answer:0,why:{en:"The statements go straight to DBHelper.ExecuteQuery one after another; the web port generates a reviewable script instead.",fa:"دستورها یکی پس از دیگری مستقیم به DBHelper.ExecuteQuery می‌روند؛ پورت وب به‌جایش یک اسکریپت قابل بررسی تولید می‌کند."}}]},{id:"legacy-connections",group:"desktop",title:{en:"Connections per module, and the empty service",fa:"اتصال برای هر ماژول، و سرویس خالی"},files:["wUtility/Drug.cs","wUtility/CommonClass.cs","wUtility/Utils/CryptographyUtils.cs","wUtility/Utils/AppSettingsManager.cs","wService/Service1.cs"],en:[{id:"modules",h:"13 modules, a key in the source",p:["The HIS was split into module databases: Totalsystem, Lab, Radio, Drug, Blood, OpRoom and seven more, 13 in all, listed in `CommonClass`. Each module has its own class (`Drug.cs`, `Lab.cs`, `Blood.cs`...), nearly identical files of about 320 lines, whose `ConnectionString` property reads and writes the module's connection strings in the app's local settings through `AppSettingsManager`, encrypted with AES.","The encryption is real AES, with a key derived by `Rfc2898DeriveBytes`, but the shared secret is a literal repeated in every module file and the salt is a constant in `CryptographyUtils`. Anyone with the program can decrypt every stored connection string, passwords included. The copy-per-module design also means a fix must be made 13 times. The web port keeps the 13 module names but replaces the rest with one vault table and a key from the environment."],examples:["modules","conn"]},{id:"service",h:"wService: a placeholder",p:["The README calls `wService` a companion Windows Service for background and scheduled operations. In the code it is the Visual Studio template: `Program.Main` runs `Service1`, whose `OnStart` and `OnStop` are empty. It is worth knowing before relying on it: no background work exists yet."],examples:["service"]}],fa:[{id:"modules",h:"13 ماژول، یک کلید در کد",p:["HIS به دیتابیس‌های ماژولی تقسیم شده بود: Totalsystem، Lab، Radio، Drug، Blood، OpRoom و هفت تای دیگر، در کل 13 تا، که در `CommonClass` فهرست شده‌اند. هر ماژول کلاس خودش را دارد (`Drug.cs`، `Lab.cs`، `Blood.cs`...)، فایل‌هایی تقریباً یکسان با حدود 320 خط، که property‌ی `ConnectionString`شان connection stringهای ماژول را از طریق `AppSettingsManager` در تنظیمات محلی اپ می‌خواند و می‌نویسد، رمزگذاری‌شده با AES.","رمزگذاری AES‌ی واقعی است، با کلیدی که `Rfc2898DeriveBytes` می‌سازد، ولی رمز مشترک یک مقدار ثابت است که در فایل هر ماژول تکرار شده و salt یک ثابت در `CryptographyUtils` است. هر کسی که برنامه را دارد می‌تواند همه‌ی connection stringهای ذخیره‌شده را، با رمزهایشان، باز کند. طراحی کپی‌برای‌هر‌ماژول یعنی هر اصلاحی باید 13 بار انجام شود. پورت وب اسم 13 ماژول را نگه می‌دارد ولی بقیه را با یک جدول vault و یک کلید از محیط عوض می‌کند."],examples:["modules","conn"]},{id:"service",h:"wService: یک جای خالی",p:["README، `wService` را یک Windows Service‌ی همراه برای کارهای پس‌زمینه و زمان‌بندی‌شده می‌نامد. در کد همان قالب Visual Studio است: `Program.Main` کلاس `Service1` را اجرا می‌کند که `OnStart` و `OnStop`ش خالی‌اند. پیش از تکیه بر آن خوب است این را بدانید: هنوز هیچ کار پس‌زمینه‌ای وجود ندارد."],examples:["service"]}],examples:{modules:{title:{en:"The 13 modules",fa:"13 ماژول"},lang:"csharp",file:"wUtility/CommonClass.cs",from:"static public List<string> ConnectedDatabases",lines:11},conn:{title:{en:"Encrypted into local settings",fa:"رمزشده در تنظیمات محلی"},lang:"csharp",file:"wUtility/Drug.cs",from:"/// //// this property for save connectionString",to:"AppSettingsManager.SetSetting(ConnectionStringName, encryptedValue);"},service:{title:{en:"An empty service",fa:"یک سرویس خالی"},lang:"csharp",file:"wService/Service1.cs",from:"protected override void OnStart(string[] args)",lines:7}},quiz:[{q:{en:"The desktop app encrypts connection strings with AES. Why is that still not safe?",fa:"اپ دسکتاپ connection stringها را با AES رمز می‌کند. چرا باز هم امن نیست؟"},options:{en:["AES is broken","The secret and salt are constants in the program, so anyone with it can decrypt","The strings are too long"],fa:["AES شکسته شده","رمز و salt ثابت‌هایی در خود برنامه‌اند، پس هر کسی که برنامه را دارد می‌تواند بازشان کند","رشته‌ها خیلی طولانی‌اند"]},answer:1,why:{en:"Encryption is only as secret as its key; here the key is in the source of every module file.",fa:"رمزگذاری فقط به اندازه‌ی کلیدش محرمانه است؛ این‌جا کلید در کد فایل هر ماژول است."}},{q:{en:"What does wService do today?",fa:"wService امروز چه کار می‌کند؟"},options:{en:["Runs scheduled schema syncs","Backs up the vault","Nothing: OnStart and OnStop are empty"],fa:["همگام‌سازی‌های زمان‌بندی‌شده‌ی schema را اجرا می‌کند","از vault پشتیبان می‌گیرد","هیچ: OnStart و OnStop خالی‌اند"]},answer:2,why:{en:"Service1 is the template with empty overrides.",fa:"Service1 همان قالب با overrideهای خالی است."}}]},{id:"reader",group:"sync",title:{en:"Reading a schema",fa:"خواندن یک schema"},files:["web/api/SchemaReader.cs","web/api/SqlReaderExtensions.cs","web/api/Models.cs"],en:[{id:"query",h:"One query, then GroupBy",p:["`SchemaReader` reads one database's tables and columns in a single query: `INFORMATION_SCHEMA.COLUMNS` joined with `TABLES` to keep base tables only (no views), left-joined with `sys.identity_columns` to know which column is an identity, for the `dbo` schema, ordered by table and column position. Each row has the type, length, precision, scale and nullability.","The result is flat, one row per column. Instead of keeping a dictionary of tables by hand, the rows are grouped with `GroupBy(row => row.TableName)` into one `TableInfo` per table; since the query already orders columns by `ORDINAL_POSITION`, every group keeps its columns in table order. The output is a `SchemaSnapshot`, plain records with no connection attached, which is what makes the differ a pure function."],examples:["sql","group"]},{id:"types",h:"A mapper and a type expression",p:["Every service in the API used to repeat `while (reader.Read()) list.Add(new ...)`. `SqlReaderExtensions.ToListAsync` does that loop once and takes the mapping as a lambda, so each call site only says how one row becomes one record.",'`ColumnInfo.SqlTypeExpression` turns metadata back into the SQL that declares it: `nvarchar(20)`, `nvarchar(MAX)` for a length of -1, `decimal(10,2)`, or the bare type. Both the comparison and the generated script use it, so "same type" means exactly "would be declared the same way". `CHARACTER_MAXIMUM_LENGTH` is already in characters for `nvarchar`, so no division by two is needed.'],examples:["tolist","type"]}],fa:[{id:"query",h:"یک query، بعد GroupBy",p:["`SchemaReader` جدول‌ها و ستون‌های یک دیتابیس را با یک query می‌خواند: `INFORMATION_SCHEMA.COLUMNS` که با `TABLES` join شده تا فقط جدول‌های پایه بمانند (نه viewها)، و با `sys.identity_columns` left join شده تا معلوم شود کدام ستون identity است، برای schema‌ی `dbo`، مرتب بر اساس جدول و جایگاه ستون. هر ردیف نوع، طول، precision، scale و nullability را دارد.","نتیجه تخت است، یک ردیف برای هر ستون. به‌جای این‌که یک dictionary از جدول‌ها دستی نگه داشته شود، ردیف‌ها با `GroupBy(row => row.TableName)` به یک `TableInfo` برای هر جدول دسته می‌شوند؛ چون query از قبل ستون‌ها را بر اساس `ORDINAL_POSITION` مرتب کرده، هر گروه ستون‌هایش را به ترتیب جدول نگه می‌دارد. خروجی یک `SchemaSnapshot` است، رکوردهای ساده بدون هیچ اتصالی، و همین differ را یک تابع خالص می‌کند."],examples:["sql","group"]},{id:"types",h:"یک mapper و یک عبارت نوع",p:["هر سرویس در API قبلاً `while (reader.Read()) list.Add(new ...)` را تکرار می‌کرد. `SqlReaderExtensions.ToListAsync` این حلقه را یک بار انجام می‌دهد و نگاشت را به‌صورت یک lambda می‌گیرد، پس هر جای صدا زدن فقط می‌گوید یک ردیف چطور یک رکورد می‌شود.",'`ColumnInfo.SqlTypeExpression` metadata را به همان SQLی برمی‌گرداند که آن را تعریف می‌کند: `nvarchar(20)`، `nvarchar(MAX)` برای طول -1، `decimal(10,2)`، یا خود نوع. هم مقایسه و هم اسکریپت تولیدشده از آن استفاده می‌کنند، پس "نوع یکسان" دقیقاً یعنی "به یک شکل تعریف می‌شود". `CHARACTER_MAXIMUM_LENGTH` برای `nvarchar` از قبل بر حسب نویسه است، پس تقسیم بر دو لازم نیست.'],examples:["tolist","type"]}],examples:{sql:{title:{en:"Columns, tables and identities",fa:"ستون‌ها، جدول‌ها و identityها"},lang:"sql",file:"web/api/SchemaReader.cs",from:'const string sql = @"',to:'ORDER BY c.TABLE_NAME, c.ORDINAL_POSITION";'},group:{title:{en:"Flat rows into tables",fa:"ردیف‌های تخت به جدول"},lang:"csharp",file:"web/api/SchemaReader.cs",from:"var tables = flatRows",lines:3},tolist:{title:{en:"One loop for every reader",fa:"یک حلقه برای هر reader"},lang:"csharp",file:"web/api/SqlReaderExtensions.cs",from:"public static async Task<List<T>> ToListAsync<T>",lines:7},type:{title:{en:"Metadata back to SQL",fa:"metadata به SQL"},lang:"csharp",file:"web/api/Models.cs",from:"public string SqlTypeExpression()",to:"return DataType;"}},quiz:[{q:{en:"Why does the query join INFORMATION_SCHEMA.TABLES with TABLE_TYPE = 'BASE TABLE'?",fa:"چرا query با INFORMATION_SCHEMA.TABLES و شرط TABLE_TYPE = 'BASE TABLE' join می‌شود؟"},options:{en:["COLUMNS also lists the columns of views, which must not be compared or recreated as tables","To get the row count","Because COLUMNS has no table names"],fa:["COLUMNS ستون‌های viewها را هم فهرست می‌کند که نباید به‌عنوان جدول مقایسه یا ساخته شوند","برای گرفتن تعداد ردیف‌ها","چون COLUMNS اسم جدول ندارد"]},answer:0,why:{en:"Without the filter, a view in the source would show up as a missing table and get a CREATE TABLE.",fa:"بدون فیلتر، یک view در مبدأ به‌صورت جدول گم‌شده ظاهر می‌شد و یک CREATE TABLE می‌گرفت."}},{q:{en:"What does SqlTypeExpression return for an nvarchar column whose length is -1?",fa:"SqlTypeExpression برای ستون nvarcharی که طولش -1 است چه برمی‌گرداند؟"},options:{en:["nvarchar(-1)","nvarchar(MAX)","nvarchar"],fa:["nvarchar(-1)","nvarchar(MAX)","nvarchar"]},answer:1,why:{en:"SQL Server reports MAX as -1; the expression turns it back into MAX so the script is valid.",fa:"SQL Server مقدار MAX را -1 گزارش می‌کند؛ عبارت آن را به MAX برمی‌گرداند تا اسکریپت معتبر باشد."}}]},{id:"differ",group:"sync",title:{en:"Comparing: source is the truth",fa:"مقایسه: مبدأ حقیقت است"},files:["web/api/SchemaDiffer.cs","web/api/Models.cs","web/db/01-schemasync-source.sql","web/db/02-schemasync-target.sql"],en:[{id:"oneway",h:"One direction, four kinds of difference",p:['`SchemaDiffer.Diff` compares a source snapshot, the desired state, with a target, what a site has now. The direction is fixed on purpose: a deployment needs "bring this site in line with the reference", not a symmetric report. For each source table it reports `MissingTable` if the target has none of that name; otherwise, for each source column, `MissingColumn`, `ColumnTypeMismatch` when the type expressions differ, or `ColumnNullabilityMismatch` when only NULL / NOT NULL differs. Names are compared case-insensitively, as SQL Server usually does.',"What the target has and the source does not (an extra column a hospital added) is not reported and therefore never dropped. A sync that deleted a site's own columns, with their data, would be far worse than one that leaves them."],examples:["tables","columns"]},{id:"demo",h:"The demo drift",p:["The two demo databases show all four kinds at once. The source has `Patients` with a 20-character `NationalCode`, a nullable `BirthDate` and a `Phone`, plus an `Appointments` table. The target has no `Appointments`, no `Phone`, a 10-character `NationalCode` and a `BirthDate` that is NOT NULL. A type mismatch is checked before nullability, so a column that differs in both is reported once, as a type mismatch, whose fix sets the nullability too."],examples:["source","target"]}],fa:[{id:"oneway",h:"یک جهت، چهار نوع تفاوت",p:['`SchemaDiffer.Diff` یک snapshot‌ی مبدأ، یعنی حالت مطلوب، را با یک مقصد، یعنی چیزی که یک سایت الان دارد، مقایسه می‌کند. جهت عمداً ثابت است: استقرار به "این سایت را هم‌راستای مرجع کن" نیاز دارد، نه به یک گزارش متقارن. برای هر جدول مبدأ، اگر مقصد جدولی با آن اسم نداشته باشد `MissingTable` گزارش می‌دهد؛ وگرنه برای هر ستون مبدأ، `MissingColumn`، یا `ColumnTypeMismatch` وقتی عبارت‌های نوع فرق دارند، یا `ColumnNullabilityMismatch` وقتی فقط NULL / NOT NULL فرق دارد. اسم‌ها بدون توجه به بزرگی حروف مقایسه می‌شوند، همان‌طور که SQL Server معمولاً می‌کند.',"چیزی که مقصد دارد و مبدأ ندارد (ستون اضافه‌ای که یک بیمارستان اضافه کرده) گزارش نمی‌شود و بنابراین هرگز حذف نمی‌شود. همگام‌سازی‌ای که ستون‌های خود سایت را با داده‌شان پاک کند خیلی بدتر از همگام‌سازی‌ای است که آن‌ها را نگه دارد."],examples:["tables","columns"]},{id:"demo",h:"فاصله‌ی نمایشی",p:["دو دیتابیس نمایشی هر چهار نوع را با هم نشان می‌دهند. مبدأ `Patients` را با `NationalCode`‌ی 20 نویسه‌ای، `BirthDate`ی nullable و یک `Phone` دارد، به‌علاوه‌ی جدول `Appointments`. مقصد `Appointments` ندارد، `Phone` ندارد، `NationalCode`ش 10 نویسه است و `BirthDate`ش NOT NULL. ناهماهنگی نوع قبل از nullability بررسی می‌شود، پس ستونی که در هر دو فرق دارد یک بار گزارش می‌شود، به‌صورت ناهماهنگی نوع، که اصلاحش nullability را هم تنظیم می‌کند."],examples:["source","target"]}],examples:{tables:{title:{en:"A missing table",fa:"یک جدول گم‌شده"},lang:"csharp",file:"web/api/SchemaDiffer.cs",from:"var targetTables = target.Tables.ToDictionary",lines:11},columns:{title:{en:"Type first, then nullability",fa:"اول نوع، بعد nullability"},lang:"csharp",file:"web/api/SchemaDiffer.cs",from:"if (!string.Equals(targetColumn.SqlTypeExpression()",lines:14},source:{title:{en:"The reference",fa:"مرجع"},lang:"sql",file:"web/db/01-schemasync-source.sql",from:"CREATE TABLE dbo.Patients (",lines:7},target:{title:{en:"The drifted site",fa:"سایتی که فاصله گرفته"},lang:"sql",file:"web/db/02-schemasync-target.sql",from:"CREATE TABLE dbo.Patients (",lines:6}},quiz:[{q:{en:"A site has an extra column Patients.Insurance that the reference does not. What does the sync do with it?",fa:"یک سایت ستون اضافه‌ی Patients.Insurance را دارد که مرجع ندارد. همگام‌سازی با آن چه می‌کند؟"},options:{en:["Drops it","Nothing: diffs only go from source to target","Adds it to the source"],fa:["حذفش می‌کند","هیچ: تفاوت‌ها فقط از مبدأ به مقصد هستند","آن را به مبدأ اضافه می‌کند"]},answer:1,why:{en:"Diff loops over source tables and columns only; target-only objects never become a diff.",fa:"Diff فقط روی جدول‌ها و ستون‌های مبدأ حلقه می‌زند؛ چیزهایی که فقط در مقصدند هرگز تفاوت نمی‌شوند."}},{q:{en:"A column is nvarchar(10) NOT NULL in the target and nvarchar(20) NULL in the source. How many diffs?",fa:"یک ستون در مقصد nvarchar(10) NOT NULL است و در مبدأ nvarchar(20) NULL. چند تفاوت؟"},options:{en:["Two: type and nullability","None","One type mismatch; nullability is only checked when the types agree"],fa:["دو: نوع و nullability","هیچ","یک ناهماهنگی نوع؛ nullability فقط وقتی بررسی می‌شود که نوع‌ها یکی باشند"]},answer:2,why:{en:"The nullability check is in the else branch of the type check, and the ALTER COLUMN for the type uses the source's nullability.",fa:"بررسی nullability در شاخه‌ی else‌ی بررسی نوع است، و ALTER COLUMN‌ی نوع از nullability‌ی مبدأ استفاده می‌کند."}}]},{id:"generator",group:"sync",title:{en:"Generating a script to review",fa:"تولید اسکریپتی برای بررسی"},files:["web/api/ScriptGenerator.cs"],en:[{id:"script",h:"A script, not a silent change",p:["The sync happens by generating T-SQL a person reads before it runs, not by changing the target behind their back. `ScriptGenerator.Generate` starts with a header saying it was generated and how many changes it holds, then goes table by table. A missing table becomes one `CREATE TABLE` with every column of the source in ordinal order, its identity and its nullability, and nothing else is generated for that table. Each statement ends with `GO`, so the script can also be pasted into SSMS or run with `sqlcmd`.","A missing column is always added as `NULL`, whatever the source says. Adding a NOT NULL column without a default fails on a table that already has rows, and site tables always have rows; `NULL` always succeeds."],examples:["create","add"]},{id:"nullable",h:"Widening, and leaving the tightening to a person",p:["For a nullability mismatch the script also only widens: it writes `ALTER COLUMN ... NULL` even when the source column is NOT NULL, with a comment in the script that says so. Tightening to NOT NULL needs every existing row to have a value first, which only someone who knows the data can backfill. The generated script is meant to never fail on existing data; the tightening is a deliberate manual follow-up, written in the script where the reviewer will see it."],examples:["nulls"]}],fa:[{id:"script",h:"یک اسکریپت، نه یک تغییر بی‌صدا",p:["همگام‌سازی با تولید T-SQLی انجام می‌شود که یک آدم قبل از اجرا آن را می‌خواند، نه با تغییر دادن مقصد پشت سرش. `ScriptGenerator.Generate` با یک سرآغاز شروع می‌کند که می‌گوید اسکریپت تولیدشده است و چند تغییر دارد، بعد جدول به جدول جلو می‌رود. جدول گم‌شده یک `CREATE TABLE` می‌شود با همه‌ی ستون‌های مبدأ به ترتیب جایگاه، identity و nullabilityشان، و برای آن جدول چیز دیگری تولید نمی‌شود. هر دستور با `GO` تمام می‌شود، پس اسکریپت را می‌شود در SSMS هم چسباند یا با `sqlcmd` اجرا کرد.","ستون گم‌شده همیشه به‌صورت `NULL` اضافه می‌شود، هر چه مبدأ بگوید. اضافه کردن ستون NOT NULL بدون default روی جدولی که ردیف دارد شکست می‌خورد، و جدول‌های سایت همیشه ردیف دارند؛ `NULL` همیشه موفق می‌شود."],examples:["create","add"]},{id:"nullable",h:"گشاد کردن، و سپردن سفت کردن به یک آدم",p:["برای ناهماهنگی nullability هم اسکریپت فقط گشاد می‌کند: حتی وقتی ستون مبدأ NOT NULL است `ALTER COLUMN ... NULL` می‌نویسد، با توضیحی در خود اسکریپت که همین را می‌گوید. سفت کردن به NOT NULL لازم دارد اول همه‌ی ردیف‌های موجود مقدار داشته باشند، و فقط کسی که داده را می‌شناسد می‌تواند آن‌ها را پر کند. اسکریپت تولیدشده قرار است هرگز روی داده‌ی موجود شکست نخورد؛ سفت کردن یک کار دستی آگاهانه‌ی بعدی است، که در اسکریپت جایی نوشته شده که بررسی‌کننده آن را ببیند."],examples:["nulls"]}],examples:{create:{title:{en:"A missing table: CREATE TABLE",fa:"جدول گم‌شده: CREATE TABLE"},lang:"csharp",file:"web/api/ScriptGenerator.cs",from:"if (missingTable is not null)",lines:7},add:{title:{en:"A missing column, always NULL",fa:"ستون گم‌شده، همیشه NULL"},lang:"csharp",file:"web/api/ScriptGenerator.cs",from:"foreach (var diff in tableDiffs.Where(d => d.Kind == DiffKind.MissingColumn))",lines:8},nulls:{title:{en:"Widen, and say so",fa:"گشاد کن، و بگو"},lang:"csharp",file:"web/api/ScriptGenerator.cs",from:"foreach (var diff in tableDiffs.Where(d => d.Kind == DiffKind.ColumnNullabilityMismatch))",lines:10}},quiz:[{q:{en:"The source has Patients.Phone NOT NULL and the target has no Phone. What line does the script contain?",fa:"مبدأ ستون Patients.Phone را NOT NULL دارد و مقصد Phone ندارد. اسکریپت چه خطی دارد؟"},options:{en:["ALTER TABLE dbo.[Patients] ADD [Phone] ... NOT NULL;","ALTER TABLE dbo.[Patients] ADD [Phone] ... NULL;","DROP TABLE dbo.[Patients];"],fa:["ALTER TABLE dbo.[Patients] ADD [Phone] ... NOT NULL;","ALTER TABLE dbo.[Patients] ADD [Phone] ... NULL;","DROP TABLE dbo.[Patients];"]},answer:1,why:{en:"Missing columns are always added as NULL so the script cannot fail on a table with rows.",fa:"ستون‌های گم‌شده همیشه NULL اضافه می‌شوند تا اسکریپت روی جدول دارای ردیف شکست نخورد."}},{q:{en:"Why does every statement end with GO?",fa:"چرا هر دستور با GO تمام می‌شود؟"},options:{en:["It commits the transaction","SQL Server requires it after ALTER","It splits the script into batches, the convention SSMS and sqlcmd use, which the executor also follows"],fa:["transaction را commit می‌کند","SQL Server بعد از ALTER لازمش دارد","اسکریپت را به دسته‌ها می‌شکند، قراردادی که SSMS و sqlcmd دارند و executor هم دنبالش می‌کند"]},answer:2,why:{en:"GO is not T-SQL; it is a batch separator that tools, and ScriptExecutor, split on.",fa:"GO جزو T-SQL نیست؛ جداکننده‌ی دسته است که ابزارها، و ScriptExecutor، روی آن جدا می‌کنند."}}]},{id:"executor",group:"sync",title:{en:"Running the script, batch by batch",fa:"اجرای اسکریپت، دسته به دسته"},files:["web/api/ScriptExecutor.cs","web/api/Program.cs","web/api/Models.cs"],en:[{id:"batches",h:"Stop at the first failure, say where",p:["`ScriptExecutor` splits the script on lines that hold only `GO` (any case, any surrounding spaces), the same rule `sqlcmd` and SSMS use, and drops batches made only of `--` comment lines, such as the header. It then runs the batches one by one on one connection. If one fails, it stops and returns `ExecuteResult(false, executed, error)`: the list of batches that did run, and the failing batch with SQL Server's message. Nothing after the failure runs.","That answer is what the page needs to tell the truth. Sending the whole script as one command would either run everything or stop somewhere unknown; with batches, the user sees exactly which changes are already on the target and which one to fix."],examples:["split","loop"]},{id:"route",h:"Two routes: compare, execute",p:["`POST /api/compare` reads both schemas, diffs them and returns the diffs with the script; `POST /api/execute` takes a target connection string and a script and runs it. Outside demo mode that is the whole tool: any connection string, any script, which is why the API key guards every route. In demo mode the execute route keeps the same shape but refuses anything except the script the server would generate right now."],examples:["execute"]}],fa:[{id:"batches",h:"در اولین شکست بایست، و بگو کجا",p:["`ScriptExecutor` اسکریپت را روی خط‌هایی که فقط `GO` دارند (با هر بزرگی حروف و هر فاصله‌ای دورش) جدا می‌کند، همان قاعده‌ای که `sqlcmd` و SSMS دارند، و دسته‌هایی را که فقط از خط‌های توضیح `--` ساخته شده‌اند، مثل سرآغاز، کنار می‌گذارد. بعد دسته‌ها را یکی‌یکی روی یک اتصال اجرا می‌کند. اگر یکی شکست بخورد، می‌ایستد و `ExecuteResult(false, executed, error)` برمی‌گرداند: فهرست دسته‌هایی که اجرا شدند، و دسته‌ی شکست‌خورده با پیام SQL Server. بعد از شکست هیچ چیزی اجرا نمی‌شود.","همین جواب است که صفحه برای گفتن حقیقت لازم دارد. فرستادن کل اسکریپت به‌صورت یک دستور یا همه چیز را اجرا می‌کرد یا جایی نامعلوم می‌ایستاد؛ با دسته‌ها کاربر دقیقاً می‌بیند کدام تغییرها روی مقصد نشسته‌اند و کدام یکی را باید درست کند."],examples:["split","loop"]},{id:"route",h:"دو مسیر: مقایسه، اجرا",p:["`POST /api/compare` هر دو schema را می‌خواند، مقایسه می‌کند و تفاوت‌ها را با اسکریپت برمی‌گرداند؛ `POST /api/execute` یک connection string‌ی مقصد و یک اسکریپت می‌گیرد و اجرایش می‌کند. بیرون از حالت دمو کل ابزار همین است: هر connection string، هر اسکریپت، و برای همین API key از همه‌ی مسیرها محافظت می‌کند. در حالت دمو مسیر اجرا همان شکل را دارد ولی هر چیزی جز اسکریپتی را که سرور همین الان تولید می‌کرد رد می‌کند."],examples:["execute"]}],examples:{split:{title:{en:"GO lines, and comment-only batches",fa:"خط‌های GO، و دسته‌های فقط توضیح"},lang:"csharp",file:"web/api/ScriptExecutor.cs",from:"private static readonly Regex GoSplitter",to:"batch.Split"},loop:{title:{en:"Stop and report",fa:"بایست و گزارش بده"},lang:"csharp",file:"web/api/ScriptExecutor.cs",from:"foreach (var batch in batches)",to:"return new ExecuteResult(true, executed, null);"},execute:{title:{en:"Execute, and its demo rule",fa:"اجرا، و قاعده‌ی دمویش"},lang:"csharp",file:"web/api/Program.cs",from:'app.MapPost("/api/execute"',to:".RequireRateLimiting(HeavyPolicy);"}},quiz:[{q:{en:"The third of five batches fails. What does the caller get back?",fa:"دسته‌ی سوم از پنج دسته شکست می‌خورد. صدازننده چه پس می‌گیرد؟"},options:{en:["Success false, the two batches that ran, and the failing batch with its error","An exception and nothing else","Success true, since most batches ran"],fa:["Success برابر false، دو دسته‌ای که اجرا شدند، و دسته‌ی شکست‌خورده با خطایش","یک exception و هیچ چیز دیگر","Success برابر true، چون بیشتر دسته‌ها اجرا شدند"]},answer:0,why:{en:"The loop catches the exception and returns ExecuteResult(false, executed, ...) right away; batches 4 and 5 never run.",fa:"حلقه exception را می‌گیرد و فوراً ExecuteResult(false, executed, ...) برمی‌گرداند؛ دسته‌های 4 و 5 هرگز اجرا نمی‌شوند."}},{q:{en:"Why are batches made only of -- lines skipped?",fa:"چرا دسته‌هایی که فقط خط‌های -- دارند رد می‌شوند؟"},options:{en:["SQL Server cannot parse comments","They are documentation like the script header, with nothing to execute","To make the script shorter"],fa:["SQL Server نمی‌تواند توضیح‌ها را بخواند","مثل سرآغاز اسکریپت مستندات‌اند و چیزی برای اجرا ندارند","تا اسکریپت کوتاه‌تر شود"]},answer:1,why:{en:"HasExecutableContent keeps a batch only if some non-empty line does not start with --.",fa:"HasExecutableContent فقط دسته‌ای را نگه می‌دارد که خط غیرخالی‌ای داشته باشد که با -- شروع نشود."}}]},{id:"apikey",group:"security",title:{en:"The API key middleware",fa:"middleware‌ی API key"},files:["web/api/Program.cs","web/frontend/proxy.conf.js"],en:[{id:"check",h:"Every /api route, compared in constant time",p:["One middleware in `Program.cs` stands in front of every route under `/api`: it reads `X-Api-Key`, compares it with the configured key, and answers 401 with `{ error }` when they differ. The comparison uses `CryptographicOperations.FixedTimeEquals` on the bytes. An ordinary string comparison stops at the first different character, so its timing leaks how much of a guess was right; a fixed-time comparison takes as long whatever the input, and the key cannot be found one character at a time.","This protects one service from another; it is not a user login. Anyone holding the key can do everything, and the README says plainly that a real deployment would still need user sign-in in front of the schema-sync pages."],examples:["middleware"]},{id:"outside",h:"What stays outside",p:["`/healthz` is outside `/api` and answers without a key, and on purpose without touching SQL: the hosting platform calls it to decide whether the app is alive, and an auto-paused free database must not make the app look dead. The static Angular files are outside too. In demo mode the middleware is skipped altogether, because the browser calls `/api` directly and cannot hold a secret; the dangerous routes are constrained instead."],examples:["health"]}],fa:[{id:"check",h:"هر مسیر /api، مقایسه‌شده در زمان ثابت",p:["یک middleware در `Program.cs` جلوی همه‌ی مسیرهای زیر `/api` می‌ایستد: `X-Api-Key` را می‌خواند، با کلید تنظیم‌شده مقایسه می‌کند، و وقتی فرق دارند با 401 و `{ error }` جواب می‌دهد. مقایسه با `CryptographicOperations.FixedTimeEquals` روی بایت‌ها انجام می‌شود. مقایسه‌ی معمولی رشته در اولین نویسه‌ی متفاوت می‌ایستد، پس زمانش لو می‌دهد چه مقدار از یک حدس درست بوده؛ مقایسه‌ی زمان ثابت با هر ورودی همان‌قدر طول می‌کشد، و کلید را نمی‌شود نویسه به نویسه پیدا کرد.","این از یک سرویس در برابر سرویس دیگر محافظت می‌کند؛ ورود کاربر نیست. هر کسی که کلید را دارد همه کار می‌تواند بکند، و README صریح می‌گوید یک استقرار واقعی هنوز جلوی صفحه‌های همگام‌سازی schema به ورود کاربر نیاز دارد."],examples:["middleware"]},{id:"outside",h:"چه چیزی بیرون می‌ماند",p:["`/healthz` بیرون از `/api` است و بدون کلید جواب می‌دهد، و عمداً بدون دست زدن به SQL: پلتفرم میزبانی آن را صدا می‌زند تا بفهمد اپ زنده است یا نه، و یک دیتابیس رایگان که خودکار متوقف شده نباید اپ را مرده نشان دهد. فایل‌های static‌ی Angular هم بیرون‌اند. در حالت دمو middleware کلاً رد می‌شود، چون مرورگر مستقیم `/api` را صدا می‌زند و نمی‌تواند رازی نگه دارد؛ به‌جایش مسیرهای خطرناک محدود می‌شوند."],examples:["health"]}],examples:{middleware:{title:{en:"The key check",fa:"بررسی کلید"},lang:"csharp",file:"web/api/Program.cs",from:"app.Use(async (context, next) =>",to:"await next();"},health:{title:{en:"Liveness without SQL",fa:"زنده بودن بدون SQL"},lang:"csharp",file:"web/api/Program.cs",from:"// Liveness only (App Service health check).",lines:3}},quiz:[{q:{en:"Why compare the key with FixedTimeEquals instead of ==?",fa:"چرا کلید با FixedTimeEquals مقایسه می‌شود و نه ==؟"},options:{en:["== does not work on byte arrays","FixedTimeEquals is faster","== stops at the first differing character, so response times would leak how much of a guess was right"],fa:["== روی آرایه‌ی بایت کار نمی‌کند","FixedTimeEquals سریع‌تر است","== در اولین نویسه‌ی متفاوت می‌ایستد، پس زمان جواب لو می‌داد چه مقدار از حدس درست بوده"]},answer:2,why:{en:"The comment says it: constant-time comparison, so response timing does not leak the key.",fa:"توضیح کد همین را می‌گوید: مقایسه‌ی زمان ثابت، تا زمان جواب کلید را لو ندهد."}},{q:{en:"Why does /healthz not query the database?",fa:"چرا /healthz از دیتابیس query نمی‌کند؟"},options:{en:["A paused serverless database would make the app look unhealthy and be restarted for no reason","It has no connection string","Because health checks must be anonymous"],fa:["یک دیتابیس serverless‌ی متوقف‌شده اپ را ناسالم نشان می‌داد و بی‌دلیل راه‌اندازی دوباره می‌شد","connection string ندارد","چون health checkها باید ناشناس باشند"]},answer:0,why:{en:"It is a liveness check only; the comment names the auto-paused free-tier database as the reason.",fa:"فقط بررسی زنده بودن است؛ توضیح کد دیتابیس رایگان خودکار متوقف‌شده را دلیلش می‌داند."}}]},{id:"demo",group:"security",title:{en:"Demo mode: a public site without an open SQL runner",fa:"حالت دمو: یک سایت عمومی بدون اجراکننده‌ی SQL‌ی باز"},files:["web/api/DemoMode.cs","web/api/Program.cs","web/frontend/src/app/services/demo.service.ts","web/db/02-schemasync-target.sql"],en:[{id:"rules",h:"Take the powers away instead of trusting the browser",p:['On a public site the browser cannot keep an API key, and without one `/api/compare` and `/api/execute` would be an open SQL runner and a probe of any network the host can reach. `Demo:Enabled=true` keeps the pages and removes those powers: compare and execute always use the two configured sandbox databases and ignore the connection strings the client sends; execute runs only the exact script the server generates from the current diff, compared after normalising line endings, and answers 409 to anything else; the connection vault is read-only (403). "Review, then apply" still holds, but no SQL a caller wrote ever runs.','Rate limits protect the free database budget: 120 requests a minute per client IP for everything, and 10 a minute for the "heavy" routes that read whole schemas or run DDL.'],examples:["execute","limits"]},{id:"reset",h:"Reset, so the next visitor can try again",p:["Once a visitor applies the script the target matches the source and there is nothing left to show. `POST /api/demo/reset` puts the drift back (the same statements as `02-schemasync-target.sql`, which the comments ask to keep in step) and restores the four demo price-group rows. Their `RowGD` keeps counting up across resets: resetting the identity would need ALTER permission, which the app's database user deliberately does not have. The Angular pages ask `/api/demo` once and adapt (no connection-string fields, a reset button), but the API enforces the rules whatever the page shows."],examples:["reset"]}],fa:[{id:"rules",h:"قدرت را بگیر، به‌جای اعتماد به مرورگر",p:['در یک سایت عمومی مرورگر نمی‌تواند API key را نگه دارد، و بدون آن `/api/compare` و `/api/execute` یک اجراکننده‌ی SQL‌ی باز و ابزاری برای کاوش هر شبکه‌ای می‌شدند که میزبان به آن دسترسی دارد. `Demo:Enabled=true` صفحه‌ها را نگه می‌دارد و این قدرت‌ها را برمی‌دارد: مقایسه و اجرا همیشه از دو دیتابیس sandbox‌ی تنظیم‌شده استفاده می‌کنند و connection stringهایی را که کلاینت می‌فرستد نادیده می‌گیرند؛ اجرا فقط دقیقاً همان اسکریپتی را اجرا می‌کند که سرور از تفاوت فعلی تولید می‌کند، که بعد از یکسان کردن انتهای خط‌ها مقایسه می‌شود، و به هر چیز دیگری 409 می‌دهد؛ vault‌ی اتصال فقط‌خواندنی است (403). "اول بررسی، بعد اعمال" هنوز برقرار است، ولی هیچ SQLی که صدازننده نوشته باشد هرگز اجرا نمی‌شود.','محدودیت نرخ از بودجه‌ی دیتابیس رایگان محافظت می‌کند: برای همه چیز 120 درخواست در دقیقه برای هر IP‌ی کلاینت، و برای مسیرهای "heavy" که کل schema را می‌خوانند یا DDL اجرا می‌کنند 10 در دقیقه.'],examples:["execute","limits"]},{id:"reset",h:"بازنشانی، تا بازدیدکننده‌ی بعدی دوباره امتحان کند",p:["وقتی بازدیدکننده‌ای اسکریپت را اعمال کرد، مقصد با مبدأ جور است و چیزی برای نشان دادن نمانده. `POST /api/demo/reset` فاصله را برمی‌گرداند (همان دستورهای `02-schemasync-target.sql`، که توضیح‌ها می‌خواهند هم‌گام نگه داشته شوند) و چهار ردیف نمایشی گروه قیمت را بازمی‌گرداند. `RowGD`شان در بازنشانی‌ها همچنان بالا می‌رود: بازنشانی identity مجوز ALTER لازم دارد که کاربر دیتابیس اپ عمداً ندارد. صفحه‌های Angular یک بار `/api/demo` را می‌پرسند و خودشان را تطبیق می‌دهند (بدون فیلدهای connection string، با دکمه‌ی بازنشانی)، ولی API قاعده‌ها را مستقل از چیزی که صفحه نشان می‌دهد اجرا می‌کند."],examples:["reset"]}],examples:{execute:{title:{en:"Only the generated script",fa:"فقط اسکریپت تولیدشده"},lang:"csharp",file:"web/api/Program.cs",from:"// Only the script the server would generate right now may run.",lines:10},limits:{title:{en:"Per-IP limits",fa:"محدودیت برای هر IP"},lang:"csharp",file:"web/api/Program.cs",from:'const string HeavyPolicy = "heavy";',lines:13},reset:{title:{en:"The drift, put back",fa:"فاصله، برگردانده‌شده"},lang:"csharp",file:"web/api/DemoMode.cs",from:`// The target's starting "drift"`,lines:12}},quiz:[{q:{en:"In demo mode a visitor edits the shown script to add a DROP TABLE and sends it to /api/execute. What happens?",fa:"در حالت دمو بازدیدکننده‌ای اسکریپت نمایش‌داده‌شده را ویرایش می‌کند تا یک DROP TABLE اضافه کند و آن را به /api/execute می‌فرستد. چه می‌شود؟"},options:{en:["It runs on the sandbox only","409: only the unmodified script the server generates now may run","It runs after a warning"],fa:["فقط روی sandbox اجرا می‌شود","409: فقط اسکریپت دست‌نخورده‌ای که سرور الان تولید می‌کند اجرا می‌شود","بعد از یک هشدار اجرا می‌شود"]},answer:1,why:{en:"The server recompares, generates its own script and runs that one, refusing a client copy that differs.",fa:"سرور دوباره مقایسه می‌کند، اسکریپت خودش را تولید و همان را اجرا می‌کند، و نسخه‌ی کلاینت را اگر فرق داشته باشد رد می‌کند."}},{q:{en:"Why is the connection vault read-only in demo mode?",fa:"چرا vault‌ی اتصال در حالت دمو فقط‌خواندنی است؟"},options:{en:["The vault key is missing on Azure","To save database space","Adding or testing a connection string makes the host connect wherever it points"],fa:["کلید vault روی Azure نیست","برای صرفه‌جویی در فضای دیتابیس","اضافه کردن یا تست یک connection string میزبان را وادار می‌کند به هر جایی که اشاره می‌کند وصل شود"]},answer:2,why:{en:"Test opens a SqlConnection to the stored string; on a public site that is a network probe for anyone.",fa:"Test یک SqlConnection به رشته‌ی ذخیره‌شده باز می‌کند؛ در سایت عمومی این ابزار کاوش شبکه برای همه است."}}]},{id:"vault",group:"security",title:{en:"The connection vault",fa:"vault‌ی اتصال"},files:["web/api/ConnectionVault.cs","web/api/SiteConnectionsService.cs","web/db/04-dbconfig.sql","web/frontend/src/app/pages/connections-page/connections-page.component.ts"],en:[{id:"gcm",h:"AES-256-GCM, with the key outside the code",p:["The web port's answer to the desktop app's local, hard-coded encryption is one table, `dbo.SiteConnections`, whose `EncryptedConnectionString` is AES-256-GCM. Each value gets a fresh random 12-byte nonce, and the stored base64 is nonce + ciphertext + 16-byte tag. GCM is authenticated: a value that was altered, or encrypted with another key, fails to decrypt instead of returning garbage.","The key comes from `CONNECTION_VAULT_KEY` (32 bytes, base64) and never from the source. Without it the vault makes a random key for the process and logs a warning: fine for local development, but every value saved becomes unreadable after a restart. That limitation is deliberate and written down, not a bug; the Azure deployment generates the key once and reuses it on every redeploy."],examples:["key","encrypt"]},{id:"never",h:"The plaintext never leaves the service",p:['`SiteConnectionsService` lists only the id, module, display name and date; there is no endpoint that returns a stored connection string. "Test" decrypts it inside the service, opens a connection and reports success or the error message. If decryption fails, the answer says the vault key changed since the value was saved, which is almost always the reason, rather than blaming the target database.'],examples:["test"],data:{kind:"tables",only:["SiteConnections"]}}],fa:[{id:"gcm",h:"AES-256-GCM، با کلید بیرون از کد",p:["جواب پورت وب به رمزگذاری محلی و کلید داخل کد اپ دسکتاپ یک جدول است، `dbo.SiteConnections`، که `EncryptedConnectionString`ش با AES-256-GCM رمز شده است. هر مقدار یک nonce‌ی تصادفی 12 بایتی تازه می‌گیرد، و base64‌ی ذخیره‌شده nonce + متن رمزشده + tag‌ی 16 بایتی است. GCM احراز اصالت دارد: مقداری که دست‌کاری شده، یا با کلید دیگری رمز شده، به‌جای برگرداندن داده‌ی بی‌معنی در رمزگشایی شکست می‌خورد.","کلید از `CONNECTION_VAULT_KEY` (32 بایت، base64) می‌آید و هرگز از کد. بدون آن vault یک کلید تصادفی برای همان process می‌سازد و یک هشدار log می‌کند: برای توسعه‌ی محلی خوب است، ولی هر مقدار ذخیره‌شده بعد از راه‌اندازی دوباره ناخوانا می‌شود. این محدودیت عمدی و نوشته‌شده است، نه یک باگ؛ استقرار Azure کلید را یک بار تولید می‌کند و در هر استقرار دوباره از همان استفاده می‌کند."],examples:["key","encrypt"]},{id:"never",h:"متن رمزنشده هرگز از سرویس بیرون نمی‌رود",p:['`SiteConnectionsService` فقط شناسه، ماژول، اسم نمایشی و تاریخ را فهرست می‌کند؛ هیچ endpointی وجود ندارد که یک connection string‌ی ذخیره‌شده را برگرداند. "Test" آن را داخل سرویس رمزگشایی می‌کند، یک اتصال باز می‌کند و موفقیت یا پیام خطا را گزارش می‌دهد. اگر رمزگشایی شکست بخورد، جواب می‌گوید کلید vault از زمان ذخیره‌ی مقدار عوض شده، که تقریباً همیشه دلیلش همین است، به‌جای این‌که تقصیر را گردن دیتابیس مقصد بیندازد.'],examples:["test"],data:{kind:"tables",only:["SiteConnections"]}}],examples:{key:{title:{en:"The key, or a warning",fa:"کلید، یا یک هشدار"},lang:"csharp",file:"web/api/ConnectionVault.cs",from:'var envKey = Environment.GetEnvironmentVariable("CONNECTION_VAULT_KEY");',lines:14},encrypt:{title:{en:"Nonce, ciphertext, tag",fa:"nonce، متن رمزشده، tag"},lang:"csharp",file:"web/api/ConnectionVault.cs",from:"public string Encrypt(string plaintext)",to:"return Convert.ToBase64String(payload);"},test:{title:{en:"Test inside, report outside",fa:"تست در داخل، گزارش به بیرون"},lang:"csharp",file:"web/api/SiteConnectionsService.cs",from:"public async Task<TestConnectionResult> TestAsync(int id)",to:"return new TestConnectionResult(false, ex.Message);"}},quiz:[{q:{en:"The API restarts without CONNECTION_VAULT_KEY. What happens when a saved connection is tested?",fa:"API بدون CONNECTION_VAULT_KEY دوباره راه‌اندازی می‌شود. وقتی یک اتصال ذخیره‌شده تست می‌شود چه می‌شود؟"},options:{en:["It works, the key is stored in the table",'The test fails with "Could not decrypt this connection (vault key changed since it was saved)"',"The API refuses to start"],fa:["کار می‌کند، کلید در جدول ذخیره شده",'تست با "Could not decrypt this connection (vault key changed since it was saved)" شکست می‌خورد',"API بالا نمی‌آید"]},answer:1,why:{en:"A new random key is made per process; GCM decryption with it fails and TestAsync reports exactly that.",fa:"برای هر process یک کلید تصادفی تازه ساخته می‌شود؛ رمزگشایی GCM با آن شکست می‌خورد و TestAsync دقیقاً همین را گزارش می‌دهد."}},{q:{en:"Why does every Encrypt call make a new random nonce?",fa:"چرا هر بار صدا زدن Encrypt یک nonce‌ی تصادفی تازه می‌سازد؟"},options:{en:["Reusing a nonce with the same GCM key breaks its security","To make the output shorter","Because the key changes each time"],fa:["استفاده‌ی دوباره از یک nonce با همان کلید GCM امنیتش را می‌شکند","تا خروجی کوتاه‌تر شود","چون کلید هر بار عوض می‌شود"]},answer:0,why:{en:"The nonce is stored in front of the ciphertext, so it need not be secret, only never repeated.",fa:"nonce جلوی متن رمزشده ذخیره می‌شود، پس لازم نیست محرمانه باشد، فقط هرگز نباید تکرار شود."}}]},{id:"doctors",group:"forms",title:{en:"Doctors and their price groups",fa:"پزشکان و گروه‌های قیمتشان"},files:["web/api/DoctorsService.cs","web/api/DoctorsModels.cs","wUtility/DoctorsPriceGroupsForm.xaml.cs","web/db/03-totalsystem.sql","web/frontend/src/app/pages/doctor-price-groups-page/doctor-price-groups-page.component.ts"],en:[{id:"same",h:"The same query, parameterised",p:["In the HIS a doctor's services carry price groups: for each doctor (`DrCode`) and kind of work (`WCode`), the centre's share of the price and a title, in `DoctorsPriceGroups` of the Totalsystem database. The desktop form selects `Dp.*` joined with `Doctors` and `Works` for the names; the web `DoctorsService` runs the same join with the columns named, and adds an optional `WHERE Dp.DrCode = @DrCode` so the page can show one doctor's groups.","Every value goes in as a SQL parameter (`@DrCode`, `@WCode`, `@CenterSharePrice`, `@Title`), with `DBNull.Value` for the optional ones. Insert returns the new key with `OUTPUT INSERTED.RowGD`, in the same statement, instead of a second query that might see another user's row."],examples:["wpf","web"]},{id:"page",h:"The page, and the tables",p:['The doctors page lists `Doctors` read-only; choosing one opens `/doctor-price-groups?drCode=...` with full add, edit and delete. The page uses `editingRowGd` for its state: `null` when nothing is being edited, `0` while adding, otherwise the row being edited. After each save it reloads from the API, so what is shown is what is in the database. The demo rows in `03-totalsystem.sql` are made up, in Persian, like the original data; in the tables below "demo" stands for that database, `TotalsystemDemo`.'],examples:["params"],data:{kind:"tables",only:["Doctors","Works","DoctorsPriceGroups"]}}],fa:[{id:"same",h:"همان query، با پارامتر",p:["در HIS خدمات یک پزشک گروه قیمت دارند: برای هر پزشک (`DrCode`) و نوع کار (`WCode`)، سهم مرکز از قیمت و یک عنوان، در جدول `DoctorsPriceGroups` از دیتابیس Totalsystem. فرم دسکتاپ `Dp.*` را با join به `Doctors` و `Works` برای اسم‌ها می‌گیرد؛ `DoctorsService`ی وب همان join را با ستون‌های نام‌برده اجرا می‌کند، و یک `WHERE Dp.DrCode = @DrCode` اختیاری اضافه می‌کند تا صفحه بتواند گروه‌های یک پزشک را نشان دهد.","هر مقدار به‌صورت پارامتر SQL وارد می‌شود (`@DrCode`، `@WCode`، `@CenterSharePrice`، `@Title`)، با `DBNull.Value` برای مقدارهای اختیاری. insert کلید تازه را با `OUTPUT INSERTED.RowGD` در همان دستور برمی‌گرداند، به‌جای query‌ی دومی که ممکن بود ردیف کاربر دیگری را ببیند."],examples:["wpf","web"]},{id:"page",h:"صفحه، و جدول‌ها",p:['صفحه‌ی پزشکان `Doctors` را فقط‌خواندنی فهرست می‌کند؛ انتخاب یکی `/doctor-price-groups?drCode=...` را با افزودن، ویرایش و حذف کامل باز می‌کند. صفحه برای وضعیتش از `editingRowGd` استفاده می‌کند: `null` وقتی چیزی در حال ویرایش نیست، `0` هنگام افزودن، وگرنه ردیفی که ویرایش می‌شود. بعد از هر ذخیره از API دوباره بار می‌کند، پس چیزی که نشان داده می‌شود همان است که در دیتابیس است. ردیف‌های نمایشی در `03-totalsystem.sql` ساختگی‌اند، به فارسی، مثل داده‌ی اصلی؛ در جدول‌های زیر "demo" یعنی همان دیتابیس، `TotalsystemDemo`.'],examples:["params"],data:{kind:"tables",only:["Doctors","Works","DoctorsPriceGroups"]}}],examples:{wpf:{title:{en:"The desktop query",fa:"query‌ی دسکتاپ"},lang:"sql",file:"wUtility/DoctorsPriceGroupsForm.xaml.cs",from:"select Dp.*, D.Name DrName,W.Name WName",lines:4},web:{title:{en:"The web query",fa:"query‌ی وب"},lang:"csharp",file:"web/api/DoctorsService.cs",from:'var sql = @"',lines:6},params:{title:{en:"Parameters, with NULLs",fa:"پارامترها، با NULL"},lang:"csharp",file:"web/api/DoctorsService.cs",from:"private static void AddUpsertParams",lines:7}},quiz:[{q:{en:"Why does the insert use OUTPUT INSERTED.RowGD?",fa:"چرا insert از OUTPUT INSERTED.RowGD استفاده می‌کند؟"},options:{en:["RowGD is not an identity","To get the new key from the same statement, with no second query that might see someone else's row","Because ExecuteNonQuery cannot insert"],fa:["RowGD یک identity نیست","تا کلید تازه را از همان دستور بگیرد، بدون query‌ی دومی که ممکن بود ردیف کس دیگری را ببیند","چون ExecuteNonQuery نمی‌تواند insert کند"]},answer:1,why:{en:"ExecuteScalarAsync reads the OUTPUT value; SELECT MAX(RowGD) afterwards could return another user's insert.",fa:"ExecuteScalarAsync مقدار OUTPUT را می‌خواند؛ SELECT MAX(RowGD) بعد از آن ممکن بود insert‌ی کاربر دیگری را برگرداند."}},{q:{en:"On the price-groups page, what does editingRowGd = 0 mean?",fa:"در صفحه‌ی گروه‌های قیمت، editingRowGd = 0 یعنی چه؟"},options:{en:["A new row is being added","Nothing is being edited","The first row is being edited"],fa:["یک ردیف تازه در حال افزودن است","چیزی در حال ویرایش نیست","ردیف اول در حال ویرایش است"]},answer:0,why:{en:"startAdd sets it to 0 and save() calls addPriceGroup for 0, updatePriceGroup otherwise; null means not editing.",fa:"startAdd آن را 0 می‌کند و save() برای 0 متد addPriceGroup را صدا می‌زند و در غیر این صورت updatePriceGroup را؛ null یعنی ویرایش نیست."}}]},{id:"dbconfig",group:"forms",title:{en:"The registry of site databases",fa:"فهرست دیتابیس‌های سایت‌ها"},files:["web/api/DbConfigService.cs","web/api/ConnectionsModels.cs","wUtility/Models/Tbl_dbConfigSetting.cs","web/db/04-dbconfig.sql"],en:[{id:"registry",h:"Which database is which module, where",p:["A hospital site had one database per module, sometimes on two SQL Server instances. `Tbl_dbConfigSetting` is the registry: the module (`fldMainDataBase`, e.g. Totalsystem or OpRoom), the database name at that site, the name of the connection the old Delphi clients used, a Persian description, whether it is active, and the first and second instance. The desktop `DatabasesForm` shows it in its top grid; the web `/db-config` page shows the same rows.",'It is read-only in both, because the original app never writes to this table either: the registry belongs to the HIS installation, and a deployment tool that edited it could point a hospital module at the wrong database. The demo rows in `04-dbconfig.sql` are fictional sites, and the table below is read from that script: "demo" in its heading stands for the demo database `dbConfigDataBasesDemo`, which also holds the vault table.'],examples:["port","rows"],data:{kind:"tables",only:["Tbl_dbConfigSetting"]}},{id:"modules",h:"The 13 module names, kept",p:["`GET /api/modules` returns the same 13 names the desktop `CommonClass` lists, from `WuModules.All`. The connections page uses them to file each vault entry under its module, so the web vault speaks the same language as the HIS sites, even though it stores the strings in a completely different way."],examples:["modules"]}],fa:[{id:"registry",h:"کدام دیتابیس کدام ماژول است، و کجا",p:["یک سایت بیمارستانی برای هر ماژول یک دیتابیس داشت، گاهی روی دو instance‌ی SQL Server. `Tbl_dbConfigSetting` همان فهرست است: ماژول (`fldMainDataBase`، مثلاً Totalsystem یا OpRoom)، اسم دیتابیس در آن سایت، اسم اتصالی که کلاینت‌های قدیمی Delphi استفاده می‌کردند، یک توضیح فارسی، فعال بودن یا نبودن، و instance‌ی اول و دوم. `DatabasesForm`ی دسکتاپ آن را در grid بالایش نشان می‌دهد؛ صفحه‌ی `/db-config`ی وب همان ردیف‌ها را نشان می‌دهد.",'در هر دو فقط‌خواندنی است، چون اپ اصلی هم هرگز در این جدول نمی‌نویسد: این فهرست مال نصب HIS است، و ابزار استقراری که آن را ویرایش کند می‌توانست یک ماژول بیمارستان را به دیتابیس اشتباه وصل کند. ردیف‌های نمایشی در `04-dbconfig.sql` سایت‌های ساختگی‌اند، و جدول زیر از همان اسکریپت خوانده شده: "demo" در عنوانش یعنی دیتابیس نمایشی `dbConfigDataBasesDemo`، که جدول vault را هم نگه می‌دارد.'],examples:["port","rows"],data:{kind:"tables",only:["Tbl_dbConfigSetting"]}},{id:"modules",h:"13 اسم ماژول، نگه‌داشته",p:["`GET /api/modules` همان 13 اسمی را که `CommonClass`ی دسکتاپ فهرست می‌کند از `WuModules.All` برمی‌گرداند. صفحه‌ی اتصال‌ها از آن‌ها استفاده می‌کند تا هر ورودی vault را زیر ماژولش بگذارد، پس vault‌ی وب به همان زبانی حرف می‌زند که سایت‌های HIS، هرچند رشته‌ها را به روشی کاملاً متفاوت ذخیره می‌کند."],examples:["modules"]}],examples:{port:{title:{en:"Read-only, as in the original",fa:"فقط‌خواندنی، مثل اصل"},lang:"csharp",file:"web/api/DbConfigService.cs",from:"// Web port of DatabasesForm.xaml.cs",lines:3},rows:{title:{en:"Fictional sites",fa:"سایت‌های ساختگی"},lang:"sql",file:"web/db/04-dbconfig.sql",from:"INSERT INTO dbo.Tbl_dbConfigSetting",lines:6},modules:{title:{en:"The module names",fa:"اسم ماژول‌ها"},lang:"csharp",file:"web/api/ConnectionsModels.cs",from:"public static readonly string[] All =",lines:5}},quiz:[{q:{en:"Why does the web port offer no way to edit Tbl_dbConfigSetting?",fa:"چرا پورت وب هیچ راهی برای ویرایش Tbl_dbConfigSetting ندارد؟"},options:{en:["SQL Server forbids it","The original never writes it either, and a wrong edit could point a module at the wrong database","The table has no primary key"],fa:["SQL Server اجازه نمی‌دهد","اصل هم هرگز در آن نمی‌نویسد، و یک ویرایش اشتباه می‌توانست ماژولی را به دیتابیس اشتباه وصل کند","جدول کلید اصلی ندارد"]},answer:1,why:{en:"DbConfigService's comment says it is read-only there and read-only here.",fa:"توضیح DbConfigService می‌گوید آن‌جا فقط‌خواندنی است و این‌جا هم."}},{q:{en:"Where do the 13 module names of /api/modules come from?",fa:"13 اسم ماژول /api/modules از کجا می‌آیند؟"},options:{en:["From Tbl_dbConfigSetting","From the vault table","From WuModules.All, a copy of the desktop list in CommonClass"],fa:["از Tbl_dbConfigSetting","از جدول vault","از WuModules.All، کپی فهرست دسکتاپ در CommonClass"]},answer:2,why:{en:"ConnectionsModels.cs points to CommonClass.cs DatabaseModelName.ConnectedDatabases as the source of the list.",fa:"ConnectionsModels.cs به CommonClass.cs DatabaseModelName.ConnectedDatabases به‌عنوان منبع فهرست اشاره می‌کند."}}]},{id:"frontend",group:"web",title:{en:"The Angular app",fa:"اپ Angular"},files:["web/frontend/src/app/app.routes.ts","web/frontend/src/app/app.config.ts","web/frontend/src/app/app.component.html","web/frontend/src/app/pages/schema-sync-page/schema-sync.service.ts","web/frontend/src/app/pages/schema-sync-page/schema-sync-page.component.ts","web/frontend/src/app/services/demo.service.ts"],en:[{id:"shell",h:"Standalone components, a Persian right-to-left shell",p:["The app is Angular 18 with standalone components: `app.config.ts` provides the HTTP client and the router, and each page imports what it uses. The shell is right-to-left with Persian labels, like the original, with a top bar for schema sync, doctors, site databases and connections; `/` redirects to `/schema-sync`. Every service calls a relative `/api`, which the dev proxy or, in production, the same origin serves.","The diff kind comes from C# as a number, since the API serialises the `DiffKind` enum without a string converter; the page keeps a table from 0-3 to Persian labels, so the two must change together."],examples:["labels"],data:{kind:"routes"}},{id:"flow",h:"Compare, read, apply, compare again",p:[`The schema-sync page shows the diffs and the generated script, and only then an "apply" button. After a successful apply it compares again on its own, keeping the apply result on screen, so the user sees "N statements ran" next to a fresh comparison that should be empty. A failure shows the executor's message with the failing batch.`,"`DemoService` asks `/api/demo` once and shares the answer with `shareReplay(1)`, so every page that needs it uses one request; if the call fails it assumes demo mode is off. In demo mode the page hides the connection-string fields, names the two sandbox databases and offers the reset."],examples:["apply","demo"]}],fa:[{id:"shell",h:"کامپوننت‌های standalone، یک پوسته‌ی فارسی راست‌به‌چپ",p:["اپ با Angular 18 و کامپوننت‌های standalone است: `app.config.ts` کلاینت HTTP و router را فراهم می‌کند، و هر صفحه چیزی را که لازم دارد import می‌کند. پوسته راست‌به‌چپ و با برچسب‌های فارسی است، مثل اصل، با یک نوار بالا برای مقایسه‌ی schema، پزشکان، دیتابیس سایت‌ها و اتصال‌ها؛ `/` به `/schema-sync` redirect می‌شود. هر سرویس یک `/api` نسبی را صدا می‌زند که proxy‌ی توسعه یا، در production، همان origin جواب می‌دهد.","نوع تفاوت از C# به‌صورت عدد می‌آید، چون API enum‌ی `DiffKind` را بدون string converter سریال می‌کند؛ صفحه جدولی از 0 تا 3 به برچسب‌های فارسی نگه می‌دارد، پس این دو باید با هم تغییر کنند."],examples:["labels"],data:{kind:"routes"}},{id:"flow",h:"مقایسه، خواندن، اعمال، مقایسه‌ی دوباره",p:['صفحه‌ی همگام‌سازی schema تفاوت‌ها و اسکریپت تولیدشده را نشان می‌دهد، و فقط بعد از آن یک دکمه‌ی "اجرا". بعد از یک اعمال موفق، خودش دوباره مقایسه می‌کند و نتیجه‌ی اعمال را روی صفحه نگه می‌دارد، پس کاربر "N دستور اجرا شد" را کنار یک مقایسه‌ی تازه می‌بیند که باید خالی باشد. شکست، پیام executor را با دسته‌ی شکست‌خورده نشان می‌دهد.',"`DemoService` یک بار `/api/demo` را می‌پرسد و جواب را با `shareReplay(1)` به اشتراک می‌گذارد، پس هر صفحه‌ای که لازمش دارد از یک درخواست استفاده می‌کند؛ اگر درخواست شکست بخورد فرض می‌کند حالت دمو خاموش است. در حالت دمو صفحه فیلدهای connection string را پنهان می‌کند، دو دیتابیس sandbox را نام می‌برد و بازنشانی را پیشنهاد می‌دهد."],examples:["apply","demo"]}],examples:{labels:{title:{en:"Diff kinds as numbers",fa:"نوع تفاوت به‌صورت عدد"},lang:"typescript",file:"web/frontend/src/app/pages/schema-sync-page/schema-sync.service.ts",from:"export const DIFF_KIND_LABELS",lines:6},apply:{title:{en:"Apply, then compare again",fa:"اعمال، بعد مقایسه‌ی دوباره"},lang:"typescript",file:"web/frontend/src/app/pages/schema-sync-page/schema-sync-page.component.ts",from:"applyScript(): void {",lines:15},demo:{title:{en:"Asked once, shared",fa:"یک بار پرسیده، به اشتراک گذاشته"},lang:"typescript",file:"web/frontend/src/app/services/demo.service.ts",from:"this.info$ = this.http.get<DemoInfo>",lines:4}},quiz:[{q:{en:"A new DiffKind is added in C# at the end of the enum. What must also change in the Angular app?",fa:"یک DiffKind تازه در انتهای enum‌ی C# اضافه می‌شود. در اپ Angular چه چیزی هم باید عوض شود؟"},options:{en:["Nothing, the label comes from the API","DIFF_KIND_LABELS, which maps the numbers 0-3 to labels","The routes"],fa:["هیچ، برچسب از API می‌آید","DIFF_KIND_LABELS، که عددهای 0 تا 3 را به برچسب نگاشت می‌کند","مسیرها"]},answer:1,why:{en:"The enum arrives as a number; without a label for 4 the page would show an empty kind.",fa:"enum به‌صورت عدد می‌رسد؛ بدون برچسبی برای 4 صفحه نوع خالی نشان می‌داد."}},{q:{en:"Why does the page compare again after a successful apply?",fa:"چرا صفحه بعد از یک اعمال موفق دوباره مقایسه می‌کند؟"},options:{en:["To show from the database itself that nothing is left to sync","Because the script must run twice","To reset the demo"],fa:["تا از خود دیتابیس نشان دهد چیزی برای همگام‌سازی نمانده","چون اسکریپت باید دو بار اجرا شود","برای بازنشانی دمو"]},answer:0,why:{en:"applyScript calls compare(true) on success, keeping the execute result, so the fresh diff list is the proof.",fa:"applyScript در صورت موفقیت compare(true) را صدا می‌زند و نتیجه‌ی اجرا را نگه می‌دارد، پس فهرست تازه‌ی تفاوت‌ها خودش اثبات است."}}]},{id:"azure",group:"web",title:{en:"The public demo on Azure",fa:"دموی عمومی روی Azure"},files:["web/infra/main.bicep","web/deploy/azure/deploy.ps1","web/db/01-schemasync-source.sql","web/db/02-schemasync-target.sql"],en:[{id:"infra",h:"One App Service, four free databases",p:["`infra/main.bicep` describes the demo: one Linux App Service (.NET 10) that serves both the API and the Angular build from the same origin, so production needs no CORS and no proxy, and an Azure SQL server with the four demo databases on the free offer. Each database is serverless, pauses after an hour idle, and on running out of its monthly free budget pauses instead of billing. The App Service plan defaults to F1, the free tier.","The app settings switch demo mode on, pass the API key and the vault key as secure parameters, and enable forwarded headers so the rate limiter sees each visitor's real IP instead of the platform's proxy."],examples:["dbs","free"]},{id:"identity",h:"No SQL password anywhere",p:["The SQL server accepts Microsoft Entra sign-in only. The web app signs in with its system-assigned managed identity (`Authentication=Active Directory Managed Identity` in the connection string, which needs the `Microsoft.Data.SqlClient.Extensions.Azure` package), so there is no password to leak. Each database script grants that identity only what that database needs: read-only on the source, DDL on the sync target (it applies scripts there), read and write on the two config databases.","`deploy.ps1` opens the SQL firewall to the deployer's IP only while `tools/DbSetup` runs the scripts, and removes the rule in a `finally`, so the hole closes even if setup fails. Secrets are generated once into a gitignored file and reused, so a redeploy never rotates the vault key out from under the stored data."],examples:["conn","grant"]}],fa:[{id:"infra",h:"یک App Service، چهار دیتابیس رایگان",p:["`infra/main.bicep` دمو را توصیف می‌کند: یک App Service‌ی لینوکس (.NET 10) که هم API و هم build‌ی Angular را از یک origin سرو می‌کند، پس production به CORS و proxy نیاز ندارد، و یک سرور Azure SQL با چهار دیتابیس نمایشی روی پیشنهاد رایگان. هر دیتابیس serverless است، بعد از یک ساعت بی‌کاری متوقف می‌شود، و وقتی بودجه‌ی رایگان ماهانه‌اش تمام شود به‌جای صورتحساب متوقف می‌شود. plan‌ی App Service به‌طور پیش‌فرض F1، یعنی رده‌ی رایگان، است.","تنظیمات اپ حالت دمو را روشن می‌کنند، API key و کلید vault را به‌صورت پارامترهای secure می‌دهند، و forwarded headers را فعال می‌کنند تا rate limiter به‌جای proxy‌ی پلتفرم IP‌ی واقعی هر بازدیدکننده را ببیند."],examples:["dbs","free"]},{id:"identity",h:"هیچ رمز SQLی در هیچ جا",p:["سرور SQL فقط ورود Microsoft Entra را می‌پذیرد. اپ وب با managed identity‌ی system-assigned خودش وارد می‌شود (`Authentication=Active Directory Managed Identity` در connection string، که پکیج `Microsoft.Data.SqlClient.Extensions.Azure` را لازم دارد)، پس رمزی برای لو رفتن وجود ندارد. اسکریپت هر دیتابیس به آن identity فقط همان چیزی را می‌دهد که آن دیتابیس لازم دارد: فقط‌خواندنی روی مبدأ، DDL روی مقصد همگام‌سازی (چون آن‌جا اسکریپت اعمال می‌کند)، خواندن و نوشتن روی دو دیتابیس تنظیمات.","`deploy.ps1` فایروال SQL را فقط تا وقتی `tools/DbSetup` اسکریپت‌ها را اجرا می‌کند برای IP‌ی استقرارکننده باز می‌کند، و قاعده را در یک `finally` حذف می‌کند، پس حتی اگر راه‌اندازی شکست بخورد سوراخ بسته می‌شود. secretها یک بار در فایلی که gitignore شده تولید و دوباره استفاده می‌شوند، پس استقرار دوباره هرگز کلید vault را زیر پای داده‌ی ذخیره‌شده عوض نمی‌کند."],examples:["conn","grant"]}],examples:{dbs:{title:{en:"The four databases",fa:"چهار دیتابیس"},lang:"bicep",file:"web/infra/main.bicep",from:"var databases = [",lines:6},free:{title:{en:"The free offer, paused when spent",fa:"پیشنهاد رایگان، متوقف وقتی تمام شود"},lang:"bicep",file:"web/infra/main.bicep",from:"useFreeLimit: true",lines:6},conn:{title:{en:"A connection string with no secret",fa:"یک connection string بدون secret"},lang:"bicep",file:"web/infra/main.bicep",from:"connectionString: 'Server=tcp:",lines:1},grant:{title:{en:"DDL only on the target",fa:"DDL فقط روی مقصد"},lang:"sql",file:"web/db/02-schemasync-target.sql",from:"-- The app applies generated scripts",lines:11}},quiz:[{q:{en:"Why does the web app's identity get db_ddladmin only on SchemaSyncDemo_Target?",fa:"چرا identity‌ی اپ وب فقط روی SchemaSyncDemo_Target نقش db_ddladmin می‌گیرد؟"},options:{en:["Azure allows DDL on one database only","The target is the only database where it applies scripts and resets the demo; elsewhere it needs no DDL","DDL is needed to read schemas"],fa:["Azure فقط روی یک دیتابیس DDL اجازه می‌دهد","مقصد تنها دیتابیسی است که در آن اسکریپت اعمال می‌کند و دمو را بازنشانی می‌کند؛ جاهای دیگر DDL لازم ندارد","برای خواندن schema به DDL نیاز است"]},answer:1,why:{en:"Least privilege per database: the source is only read, the config databases only read and written.",fa:"کمترین دسترسی برای هر دیتابیس: مبدأ فقط خوانده می‌شود، دیتابیس‌های تنظیمات فقط خوانده و نوشته می‌شوند."}},{q:{en:"Why does deploy.ps1 delete the Deployer firewall rule in a finally block?",fa:"چرا deploy.ps1 قاعده‌ی فایروال Deployer را در یک بلوک finally حذف می‌کند؟"},options:{en:["Bicep cannot delete rules","To save money","So the opening for the deployer's IP closes even when the database setup fails"],fa:["Bicep نمی‌تواند قاعده‌ها را حذف کند","برای صرفه‌جویی در هزینه","تا راه باز برای IP‌ی استقرارکننده حتی وقتی راه‌اندازی دیتابیس شکست می‌خورد بسته شود"]},answer:2,why:{en:"The comment says the hole only exists while the scripts run; finally runs on success and on error.",fa:"توضیح کد می‌گوید این سوراخ فقط تا وقتی اسکریپت‌ها اجرا می‌شوند وجود دارد؛ finally هم در موفقیت و هم در خطا اجرا می‌شود."}}]}],o={project:e,repo:t,path:a,scan:s,groups:n,pages:i};export{o as default,n as groups,i as pages,a as path,e as project,t as repo,s as scan};
